function intake_clinicintakepolicy_versi.prosrc:
"
DECLARE
    latest_version pg_catalog.int8 := 0;
BEGIN
    SELECT latest_row.version
      INTO latest_version
      FROM clinic_app.intake_clinicintakepolicy AS latest_row
     WHERE latest_row.organization_id = NEW.organization_id AND latest_row.clinic_id = NEW.clinic_id
     ORDER BY latest_row.version DESC
     LIMIT 1;
    latest_version := COALESCE(latest_version, 0);
    IF NEW.version IS DISTINCT FROM latest_version + 1 THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'intake_identity_version_check',
            MESSAGE = 'identity versions must follow the latest version';
    END IF;
    RETURN NEW;
END;
"

function intake_emergencycontact_version.definition:
"CREATE OR REPLACE FUNCTION clinic_app.intake_emergencycontact_version_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'clinic_app'
AS $function$
DECLARE
    latest_version pg_catalog.int8 := 0;
    latest_retired pg_catalog.timestamptz;
BEGIN
    SELECT latest_row.version, latest_row.retired_at
      INTO latest_version, latest_retired
      FROM clinic_app.intake_emergencycontact AS latest_row
     WHERE latest_row.organization_id = NEW.organization_id AND latest_row.patient_id = NEW.patient_id AND latest_row.sequence = NEW.sequence
     ORDER BY latest_row.version DESC
     LIMIT 1;
    latest_version := COALESCE(latest_version, 0);
    IF NEW.version IS DISTINCT FROM latest_version + 1 THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'intake_identity_version_check',
            MESSAGE = 'identity versions must follow the latest version';
    END IF;
    IF NEW.retired_at IS NOT NULL
        AND (latest_version = 0 OR latest_retired IS NOT NULL)
    THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'intake_identity_version_check',
            MESSAGE = 'only an active identity version can be retired';
    END IF;
    RETURN NEW;
END;
$function$
"

