function intake_correction_guard_v1().definition:
"CREATE OR REPLACE FUNCTION clinic_app.intake_correction_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'clinic_app'
AS $function$
DECLARE
    produced_patient pg_catalog.uuid;
    produced_clinic pg_catalog.uuid;
    produced_version pg_catalog.int8;
    superseded pg_catalog.uuid;
BEGIN
    SELECT produced_row.patient_id, produced_row.clinic_id, produced_row.version
      INTO produced_patient, produced_clinic, produced_version
      FROM clinic_app.intake_patientdemographics AS produced_row
     WHERE produced_row.organization_id = NEW.organization_id
       AND produced_row.id = NEW.demographics_id;
    IF produced_version IS NULL
        OR produced_patient IS DISTINCT FROM NEW.patient_id
        OR produced_clinic IS DISTINCT FROM NEW.clinic_id
    THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'intake_correction_binding_check',
            MESSAGE = 'a correction receipt must bind its own version';
    END IF;
    SELECT previous_row.id INTO superseded
      FROM clinic_app.intake_patientdemographics AS previous_row
     WHERE previous_row.organization_id = NEW.organization_id
       AND previous_row.patient_id = NEW.patient_id
       AND previous_row.version = produced_version - 1;
    IF NEW.previous_id IS DISTINCT FROM superseded THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'intake_correction_binding_check',
            MESSAGE = 'a correction receipt must name the superseded version';
    END IF;
    NEW.created_at := pg_catalog.transaction_timestamp();
    RETURN NEW;
END;
$function$
"

