function scheduling_lifecycle_guard().definition:
"CREATE OR REPLACE FUNCTION clinic_app.scheduling_lifecycle_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'clinic_app', 'pg_temp'
AS $function$
DECLARE
 actor uuid;
 patient boolean;
 moment timestamptz := clinic_app.scheduling_clock();
 approval boolean;
 ttl integer;
 edge text;
 allowed boolean := false;
BEGIN
 BEGIN
  actor := NULLIF(current_setting('app.current_user_id',true),'')::uuid;
 EXCEPTION WHEN invalid_text_representation THEN
  RAISE EXCEPTION 'scheduling access denied' USING ERRCODE='42501';
 END;
 patient := NULLIF(current_setting('app.current_patient_session',true),'')
  IS NOT NULL;
 SELECT c.self_booking_requires_approval, c.hold_ttl_minutes INTO approval, ttl
  FROM clinic_app.identity_clinicconfiguration c
  WHERE c.clinic_id=NEW.clinic_id AND c.organization_id=NEW.organization_id
  ORDER BY c.version DESC LIMIT 1;
 approval := coalesce(approval,false);
 ttl := coalesce(ttl,10);
 IF TG_OP='INSERT' THEN
  NEW.revision := 1;
  NEW.transitioned_at := moment;
  NEW.hold_expires_at := NULL;
  NEW.last_command_id := NULL;
  -- A born-cancelled row is terminal and non-occupying (legacy insert shape).
  IF NEW.status NOT IN ('requested','held','scheduled','cancelled') THEN
   RAISE EXCEPTION 'illegal appointment transition' USING ERRCODE='23514',
    CONSTRAINT='scheduling_appointment_transition_check';
  END IF;
  IF patient THEN
   IF NOT EXISTS (SELECT 1 FROM clinic_app.patient_booking_scope() s
    WHERE s.organization_id=NEW.organization_id AND s.clinic_id=NEW.clinic_id
     AND s.patient_id=NEW.patient_id) THEN
    RAISE EXCEPTION 'scheduling access denied' USING ERRCODE='42501';
   END IF;
   -- Patients never create service bookings (no todo 21 book authority).
   IF NEW.service_type_id IS NOT NULL THEN
    RAISE EXCEPTION 'scheduling access denied' USING ERRCODE='42501';
   END IF;
   IF (NEW.status='requested') <> approval THEN
    RAISE EXCEPTION 'self-booking policy' USING ERRCODE='23514',
     CONSTRAINT='scheduling_appointment_request_policy_check';
   END IF;
  ELSIF NEW.status='requested' THEN
   RAISE EXCEPTION 'scheduling access denied' USING ERRCODE='42501';
  ELSIF NEW.status='held' THEN
   IF NOT (clinic_app.has_permission('appointment.book',NEW.clinic_id,NULL)
    OR (NEW.practitioner_id=actor
     AND clinic_app.has_permission('appointment.book_own',NEW.clinic_id,NULL))) THEN
    RAISE EXCEPTION 'scheduling access denied' USING ERRCODE='42501';
   END IF;
  END IF;
  IF NEW.status='held' THEN
   NEW.hold_expires_at := moment + make_interval(mins => ttl);
  END IF;
  IF NEW.status IN ('held','scheduled') AND (patient OR NEW.organization_id::text
    = current_setting('app.current_tenant',true)) THEN
   PERFORM clinic_app.scheduling_release_due_holds(NEW.id,NEW.organization_id,
    NEW.practitioner_id,NEW.patient_id,NEW.resource_ids,NEW.start_at,NEW.end_at);
  END IF;
  RETURN NEW;
 END IF;
 -- Lifecycle v2 bindings are immutable; pre-v2 columns keep their prior rules.
 IF ROW(NEW.id,NEW.organization_id,NEW.clinic_id,NEW.series_id,NEW.series_index,
   NEW.payer_membership_id,NEW.authorization_reference)
  IS DISTINCT FROM ROW(OLD.id,OLD.organization_id,OLD.clinic_id,OLD.series_id,
   OLD.series_index,OLD.payer_membership_id,OLD.authorization_reference) THEN
  RAISE EXCEPTION 'appointment identity is immutable' USING ERRCODE='23514',
   CONSTRAINT='scheduling_appointment_identity_check';
 END IF;
 NEW.revision := OLD.revision + 1;
 NEW.hold_expires_at := OLD.hold_expires_at;
 NEW.transitioned_at := OLD.transitioned_at;
 -- Cancelled rows stay owned by the legacy terminal guard (terminal_check).
 IF OLD.status='cancelled' THEN
  RETURN NEW;
 END IF;
 IF NEW.status=OLD.status THEN
  IF OLD.status<>'scheduled' AND ROW(NEW.start_at,NEW.end_at)
    IS DISTINCT FROM ROW(OLD.start_at,OLD.end_at) THEN
   RAISE EXCEPTION 'illegal appointment transition' USING ERRCODE='23514',
    CONSTRAINT='scheduling_appointment_transition_check';
  END IF;
  RETURN NEW;
 END IF;
 edge := OLD.status || '>' || NEW.status;
 IF edge NOT IN ('requested>held','requested>scheduled','requested>cancelled',
   'held>scheduled','held>cancelled','held>expired','scheduled>arrived',
   'scheduled>cancelled','scheduled>no_show','arrived>in_progress',
   'arrived>cancelled','in_progress>completed')
  OR (edge<>'scheduled>cancelled' AND ROW(NEW.start_at,NEW.end_at)
   IS DISTINCT FROM ROW(OLD.start_at,OLD.end_at)) THEN
  RAISE EXCEPTION 'illegal appointment transition' USING ERRCODE='23514',
   CONSTRAINT='scheduling_appointment_transition_check';
 END IF;
 IF edge IN ('requested>held','requested>scheduled','held>scheduled') THEN
  allowed := clinic_app.has_permission('appointment.book',OLD.clinic_id,NULL)
   OR (OLD.practitioner_id=actor
    AND clinic_app.has_permission('appointment.book_own',OLD.clinic_id,NULL));
 ELSIF edge IN ('requested>cancelled','held>cancelled','scheduled>arrived',
   'scheduled>no_show','arrived>cancelled') THEN
  allowed := clinic_app.has_permission('appointment.move',OLD.clinic_id,NULL)
   OR (OLD.practitioner_id=actor
    AND clinic_app.has_permission('appointment.move_own',OLD.clinic_id,NULL));
 ELSIF edge IN ('arrived>in_progress','in_progress>completed') THEN
  allowed := OLD.practitioner_id=actor
   AND clinic_app.has_permission('appointment.move_own',OLD.clinic_id,NULL);
 ELSIF edge='held>expired' THEN
  allowed := actor IS NULL AND NOT patient;
 ELSIF edge='scheduled>cancelled' THEN
  -- Legacy authority is retained unchanged (todo 6 parity): the legacy
  -- cancellation service and the patient guard decide this edge.
  allowed := true;
 END IF;
 IF edge IN ('held>scheduled','held>cancelled','requested>cancelled') AND patient
  AND EXISTS (SELECT 1 FROM clinic_app.patient_booking_scope() s
   WHERE s.organization_id=OLD.organization_id AND s.clinic_id=OLD.clinic_id
    AND s.patient_id=OLD.patient_id) THEN
  allowed := true;
 END IF;
 IF NOT coalesce(allowed,false) THEN
  RAISE EXCEPTION 'scheduling access denied' USING ERRCODE='42501';
 END IF;
 IF edge='held>scheduled' AND clinic_app.scheduling_hold_due(OLD.hold_expires_at)
 THEN
  RAISE EXCEPTION 'hold expired' USING ERRCODE='23514',
   CONSTRAINT='scheduling_appointment_hold_expired';
 END IF;
 IF edge='held>expired'
  AND NOT clinic_app.scheduling_hold_due(OLD.hold_expires_at) THEN
  RAISE EXCEPTION 'illegal appointment transition' USING ERRCODE='23514',
   CONSTRAINT='scheduling_appointment_transition_check';
 END IF;
 IF edge='scheduled>no_show' AND OLD.start_at>moment THEN
  RAISE EXCEPTION 'no-show before start' USING ERRCODE='23514',
   CONSTRAINT='scheduling_appointment_no_show_deadline';
 END IF;
 NEW.transitioned_at := moment;
 IF NEW.status='cancelled' AND NEW.cancelled_at IS NULL THEN
  NEW.cancelled_at := moment;
 END IF;
 IF NEW.status='held' THEN
  NEW.hold_expires_at := moment + make_interval(mins => ttl);
 END IF;
 IF OLD.status='requested' AND NEW.status IN ('held','scheduled') THEN
  PERFORM clinic_app.scheduling_release_due_holds(NEW.id,NEW.organization_id,
   NEW.practitioner_id,NEW.patient_id,NEW.resource_ids,NEW.start_at,NEW.end_at);
 END IF;
 RETURN NEW;
END $function$
"

function scheduling_lifecycle_guard().prosrc:
"
DECLARE
 actor uuid;
 patient boolean;
 moment timestamptz := clinic_app.scheduling_clock();
 approval boolean;
 ttl integer;
 edge text;
 allowed boolean := false;
BEGIN
 BEGIN
  actor := NULLIF(current_setting('app.current_user_id',true),'')::uuid;
 EXCEPTION WHEN invalid_text_representation THEN
  RAISE EXCEPTION 'scheduling access denied' USING ERRCODE='42501';
 END;
 patient := NULLIF(current_setting('app.current_patient_session',true),'')
  IS NOT NULL;
 SELECT c.self_booking_requires_approval, c.hold_ttl_minutes INTO approval, ttl
  FROM clinic_app.identity_clinicconfiguration c
  WHERE c.clinic_id=NEW.clinic_id AND c.organization_id=NEW.organization_id
  ORDER BY c.version DESC LIMIT 1;
 approval := coalesce(approval,false);
 ttl := coalesce(ttl,10);
 IF TG_OP='INSERT' THEN
  NEW.revision := 1;
  NEW.transitioned_at := moment;
  NEW.hold_expires_at := NULL;
  NEW.last_command_id := NULL;
  -- A born-cancelled row is terminal and non-occupying (legacy insert shape).
  IF NEW.status NOT IN ('requested','held','scheduled','cancelled') THEN
   RAISE EXCEPTION 'illegal appointment transition' USING ERRCODE='23514',
    CONSTRAINT='scheduling_appointment_transition_check';
  END IF;
  IF patient THEN
   IF NOT EXISTS (SELECT 1 FROM clinic_app.patient_booking_scope() s
    WHERE s.organization_id=NEW.organization_id AND s.clinic_id=NEW.clinic_id
     AND s.patient_id=NEW.patient_id) THEN
    RAISE EXCEPTION 'scheduling access denied' USING ERRCODE='42501';
   END IF;
   -- Patients never create service bookings (no todo 21 book authority).
   IF NEW.service_type_id IS NOT NULL THEN
    RAISE EXCEPTION 'scheduling access denied' USING ERRCODE='42501';
   END IF;
   IF (NEW.status='requested') <> approval THEN
    RAISE EXCEPTION 'self-booking policy' USING ERRCODE='23514',
     CONSTRAINT='scheduling_appointment_request_policy_check';
   END IF;
  ELSIF NEW.status='requested' THEN
   RAISE EXCEPTION 'scheduling access denied' USING ERRCODE='42501';
  ELSIF NEW.status='held' THEN
   IF NOT (clinic_app.has_permission('appointment.book',NEW.clinic_id,NULL)
    OR (NEW.practitioner_id=actor
     AND clinic_app.has_permission('appointment.book_own',NEW.clinic_id,NULL))) THEN
    RAISE EXCEPTION 'scheduling access denied' USING ERRCODE='42501';
   END IF;
  END IF;
  IF NEW.status='held' THEN
   NEW.hold_expires_at := moment + make_interval(mins => ttl);
  END IF;
  IF NEW.status IN ('held','scheduled') AND (patient OR NEW.organization_id::text
    = current_setting('app.current_tenant',true)) THEN
   PERFORM clinic_app.scheduling_release_due_holds(NEW.id,NEW.organization_id,
    NEW.practitioner_id,NEW.patient_id,NEW.resource_ids,NEW.start_at,NEW.end_at);
  END IF;
  RETURN NEW;
 END IF;
 -- Lifecycle v2 bindings are immutable; pre-v2 columns keep their prior rules.
 IF ROW(NEW.id,NEW.organization_id,NEW.clinic_id,NEW.series_id,NEW.series_index,
   NEW.payer_membership_id,NEW.authorization_reference)
  IS DISTINCT FROM ROW(OLD.id,OLD.organization_id,OLD.clinic_id,OLD.series_id,
   OLD.series_index,OLD.payer_membership_id,OLD.authorization_reference) THEN
  RAISE EXCEPTION 'appointment identity is immutable' USING ERRCODE='23514',
   CONSTRAINT='scheduling_appointment_identity_check';
 END IF;
 NEW.revision := OLD.revision + 1;
 NEW.hold_expires_at := OLD.hold_expires_at;
 NEW.transitioned_at := OLD.transitioned_at;
 -- Cancelled rows stay owned by the legacy terminal guard (terminal_check).
 IF OLD.status='cancelled' THEN
  RETURN NEW;
 END IF;
 IF NEW.status=OLD.status THEN
  IF OLD.status<>'scheduled' AND ROW(NEW.start_at,NEW.end_at)
    IS DISTINCT FROM ROW(OLD.start_at,OLD.end_at) THEN
   RAISE EXCEPTION 'illegal appointment transition' USING ERRCODE='23514',
    CONSTRAINT='scheduling_appointment_transition_check';
  END IF;
  RETURN NEW;
 END IF;
 edge := OLD.status || '>' || NEW.status;
 IF edge NOT IN ('requested>held','requested>scheduled','requested>cancelled',
   'held>scheduled','held>cancelled','held>expired','scheduled>arrived',
   'scheduled>cancelled','scheduled>no_show','arrived>in_progress',
   'arrived>cancelled','in_progress>completed')
  OR (edge<>'scheduled>cancelled' AND ROW(NEW.start_at,NEW.end_at)
   IS DISTINCT FROM ROW(OLD.start_at,OLD.end_at)) THEN
  RAISE EXCEPTION 'illegal appointment transition' USING ERRCODE='23514',
   CONSTRAINT='scheduling_appointment_transition_check';
 END IF;
 IF edge IN ('requested>held','requested>scheduled','held>scheduled') THEN
  allowed := clinic_app.has_permission('appointment.book',OLD.clinic_id,NULL)
   OR (OLD.practitioner_id=actor
    AND clinic_app.has_permission('appointment.book_own',OLD.clinic_id,NULL));
 ELSIF edge IN ('requested>cancelled','held>cancelled','scheduled>arrived',
   'scheduled>no_show','arrived>cancelled') THEN
  allowed := clinic_app.has_permission('appointment.move',OLD.clinic_id,NULL)
   OR (OLD.practitioner_id=actor
    AND clinic_app.has_permission('appointment.move_own',OLD.clinic_id,NULL));
 ELSIF edge IN ('arrived>in_progress','in_progress>completed') THEN
  allowed := OLD.practitioner_id=actor
   AND clinic_app.has_permission('appointment.move_own',OLD.clinic_id,NULL);
 ELSIF edge='held>expired' THEN
  allowed := actor IS NULL AND NOT patient;
 ELSIF edge='scheduled>cancelled' THEN
  -- Legacy authority is retained unchanged (todo 6 parity): the legacy
  -- cancellation service and the patient guard decide this edge.
  allowed := true;
 END IF;
 IF edge IN ('held>scheduled','held>cancelled','requested>cancelled') AND patient
  AND EXISTS (SELECT 1 FROM clinic_app.patient_booking_scope() s
   WHERE s.organization_id=OLD.organization_id AND s.clinic_id=OLD.clinic_id
    AND s.patient_id=OLD.patient_id) THEN
  allowed := true;
 END IF;
 IF NOT coalesce(allowed,false) THEN
  RAISE EXCEPTION 'scheduling access denied' USING ERRCODE='42501';
 END IF;
 IF edge='held>scheduled' AND clinic_app.scheduling_hold_due(OLD.hold_expires_at)
 THEN
  RAISE EXCEPTION 'hold expired' USING ERRCODE='23514',
   CONSTRAINT='scheduling_appointment_hold_expired';
 END IF;
 IF edge='held>expired'
  AND NOT clinic_app.scheduling_hold_due(OLD.hold_expires_at) THEN
  RAISE EXCEPTION 'illegal appointment transition' USING ERRCODE='23514',
   CONSTRAINT='scheduling_appointment_transition_check';
 END IF;
 IF edge='scheduled>no_show' AND OLD.start_at>moment THEN
  RAISE EXCEPTION 'no-show before start' USING ERRCODE='23514',
   CONSTRAINT='scheduling_appointment_no_show_deadline';
 END IF;
 NEW.transitioned_at := moment;
 IF NEW.status='cancelled' AND NEW.cancelled_at IS NULL THEN
  NEW.cancelled_at := moment;
 END IF;
 IF NEW.status='held' THEN
  NEW.hold_expires_at := moment + make_interval(mins => ttl);
 END IF;
 IF OLD.status='requested' AND NEW.status IN ('held','scheduled') THEN
  PERFORM clinic_app.scheduling_release_due_holds(NEW.id,NEW.organization_id,
   NEW.practitioner_id,NEW.patient_id,NEW.resource_ids,NEW.start_at,NEW.end_at);
 END IF;
 RETURN NEW;
END "

function scribe_consent_fence().prosrc:
"
DECLARE clinic uuid; purpose text;
BEGIN
 IF TG_TABLE_NAME='consent_consenttext' THEN
  clinic:=NEW.clinic_id; purpose:=NEW.purpose;
 ELSE
  SELECT a.clinic_id,t.purpose INTO clinic,purpose
   FROM clinic_app.consent_consentacceptance a
   JOIN clinic_app.consent_consenttext t ON t.id=a.text_id
   WHERE a.id=NEW.acceptance_id;
 END IF;
 IF purpose='consultation_recording' THEN
  PERFORM pg_advisory_xact_lock(hashtextextended(
   'clinic-lock-v1:comms-subject:scribe-consent:'||clinic,0));
 END IF;
 RETURN NEW;
END
"

function ai_ledger_guard().definition:
"CREATE OR REPLACE FUNCTION clinic_app.ai_ledger_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'clinic_app', 'pg_temp'
AS $function$
DECLARE source clinic_app.ai_aiartifact; config clinic_app.ai_modelconfiguration;
 invocation clinic_app.ai_aiinvocation; policy jsonb; usage record;
 reservation bigint; amount bigint;
BEGIN
 IF TG_OP IN ('DELETE','TRUNCATE') THEN
  RAISE EXCEPTION 'AI history is retained' USING ERRCODE='23514';
 END IF;
 IF TG_TABLE_NAME='ai_aiartifact' THEN
  IF TG_OP<>'INSERT' OR NEW.user_id IS DISTINCT FROM
   NULLIF(current_setting('app.current_user_id',true),'')::uuid
  OR NOT clinic_app.ai_staff(NEW.clinic_id,NEW.purpose,NEW.patient_enrollment_id)
  OR NEW.content IS NULL OR octet_length(NEW.content)>1056768
  OR NEW.expires_at<=statement_timestamp() THEN
   RAISE EXCEPTION 'AI artifact denied' USING ERRCODE='23514';
  END IF;
  IF NEW.kind='output' THEN
   SELECT * INTO invocation FROM clinic_app.ai_aiinvocation
    WHERE id=NEW.invocation_id;
   SELECT * INTO source FROM clinic_app.ai_aiartifact
    WHERE id=invocation.inputs_ref_id;
   IF invocation.id IS NULL OR invocation.status<>'reserved'
   OR (NEW.organization_id,NEW.clinic_id,NEW.user_id,NEW.purpose)
    IS DISTINCT FROM (invocation.organization_id,invocation.clinic_id,
     invocation.user_id,invocation.purpose)
   OR NEW.patient_enrollment_id IS DISTINCT FROM source.patient_enrollment_id
   OR NEW.method<>source.method THEN
    RAISE EXCEPTION 'AI artifact binding denied' USING ERRCODE='23514';
   END IF;
  END IF;
  NEW.created_at:=statement_timestamp();
  RETURN NEW;
 END IF;
 IF TG_TABLE_NAME='ai_aicircuit' THEN
  IF TG_OP='UPDATE' THEN
   IF NOT (current_setting('role')='clinic_owner'
    OR (current_setting('role')='none' AND session_user='clinic_owner'))
   OR (to_jsonb(NEW)-'closed_at') IS DISTINCT FROM (to_jsonb(OLD)-'closed_at')
   OR OLD.closed_at IS NOT NULL OR NEW.closed_at IS NULL THEN
    RAISE EXCEPTION 'AI circuit transition denied' USING ERRCODE='23514';
   END IF;
   NEW.closed_at:=statement_timestamp();
  ELSE
   IF NEW.closed_at IS NOT NULL OR NOT EXISTS (
    SELECT 1 FROM clinic_app.ai_aiinvocation i
    WHERE i.organization_id=NEW.organization_id
     AND i.configuration_id=NEW.configuration_id
     AND i.status='failed' AND i.reason_code='provider_timeout'
     AND i.user_id=NULLIF(current_setting('app.current_user_id',true),'')::uuid
     AND i.settled_at>coalesce((
      SELECT max(prior.closed_at) FROM clinic_app.ai_aicircuit prior
      WHERE prior.organization_id=NEW.organization_id
       AND prior.configuration_id=NEW.configuration_id
     ),'-infinity'::timestamptz)
   ) THEN RAISE EXCEPTION 'AI circuit binding denied' USING ERRCODE='23514';
   END IF;
   NEW.opened_at:=statement_timestamp();
  END IF;
  RETURN NEW;
 END IF;
 SELECT * INTO source FROM clinic_app.ai_aiartifact WHERE id=NEW.inputs_ref_id;
 SELECT * INTO config FROM clinic_app.ai_modelconfiguration
  WHERE id=NEW.configuration_id;
 IF source.id IS NULL OR config.id IS NULL
 OR (NEW.organization_id,NEW.clinic_id,NEW.user_id,NEW.purpose)
  IS DISTINCT FROM
  (source.organization_id,source.clinic_id,source.user_id,source.purpose)
 OR NEW.config_version<>config.version OR NEW.purpose<>config.purpose
 OR NEW.user_id IS DISTINCT FROM
   NULLIF(current_setting('app.current_user_id',true),'')::uuid
 OR NEW.prompt_sha256 !~ '^[a-f0-9]{64}$' THEN
  RAISE EXCEPTION 'AI invocation binding denied' USING ERRCODE='23514';
 END IF;
 IF TG_OP='INSERT' THEN
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'ai-budget:'||NEW.organization_id,0));
  policy:=clinic_app.ai_organization_policy();
  reservation:=NEW.limit_tokens_in::bigint*
   greatest(config.input_micros,config.cached_micros)
   +NEW.limit_tokens_out::bigint*config.output_micros
   +NEW.limit_audio_seconds::bigint*config.audio_micros;
  SELECT * INTO usage FROM clinic_app.ai_budget_usage(NEW.purpose);
  IF NEW.status<>'reserved' OR NEW.operation_id IS NOT NULL
  OR NEW.tokens_in<>0 OR NEW.tokens_out<>0 OR NEW.tokens_cached<>0
  OR NEW.audio_seconds<>0 OR NEW.cost_micros<>0 OR NEW.cost_minor<>0
  OR NEW.latency_ms<>0 OR NEW.reason_code<>'' OR NEW.settled_at IS NOT NULL
  OR source.kind<>'input' OR source.expires_at<=statement_timestamp()
  OR NOT clinic_app.ai_staff(source.clinic_id,source.purpose,
   source.patient_enrollment_id)
  OR config.state<>'active' OR config.approval_ref=''
  OR NEW.reserved_micros<>reservation
  OR NOT coalesce((policy->>'enabled')::boolean,false)
  OR NOT (policy->'purposes') ? NEW.purpose
  OR coalesce(usage.total_micros+reservation>
   (policy->>'monthly_budget_micros')::numeric,true)
  OR coalesce(usage.purpose_micros+reservation>
   (policy->'purpose_budgets'->>NEW.purpose)::numeric,true)
  OR NOT EXISTS (SELECT 1 FROM clinic_app.ai_gatewayswitch g
    WHERE g.id=1 AND g.enabled AND g.approved_regions ? config.region)
  THEN RAISE EXCEPTION 'AI reservation denied' USING ERRCODE='23514'; END IF;
  NEW.created_at:=statement_timestamp();
  RETURN NEW;
 END IF;
 IF (to_jsonb(NEW)-ARRAY['operation_id','status','reason_code','tokens_in',
  'tokens_out','tokens_cached','audio_seconds','cost_micros','cost_minor',
  'latency_ms','settled_at']) IS DISTINCT FROM
  (to_jsonb(OLD)-ARRAY['operation_id','status','reason_code','tokens_in',
   'tokens_out','tokens_cached','audio_seconds','cost_micros','cost_minor',
   'latency_ms','settled_at']) OR OLD.status<>'reserved' THEN
  RAISE EXCEPTION 'AI invocation immutable terms' USING ERRCODE='23514';
 END IF;
 IF NEW.operation_id IS DISTINCT FROM OLD.operation_id THEN
  IF OLD.operation_id IS NOT NULL OR NEW.status<>'reserved'
  OR (to_jsonb(NEW)-'operation_id') IS DISTINCT FROM
    (to_jsonb(OLD)-'operation_id')
  OR NOT EXISTS (SELECT 1 FROM clinic_app.comms_integrationoperation o
   WHERE o.id=NEW.operation_id AND o.kind='action' AND o.provider='ai_gateway'
    AND o.subject_type='ai.invocation' AND o.subject_id=NEW.id
    AND o.clinic_id=NEW.clinic_id AND o.organization_id=NEW.organization_id
    AND o.actor_id=NEW.user_id AND o.payload_digest=NEW.prompt_sha256)
  THEN RAISE EXCEPTION 'AI outbox binding denied' USING ERRCODE='23514'; END IF;
  RETURN NEW;
 END IF;
 amount:=(NEW.tokens_in-NEW.tokens_cached)::bigint*config.input_micros
  +NEW.tokens_cached::bigint*config.cached_micros
  +NEW.tokens_out::bigint*config.output_micros
  +NEW.audio_seconds::bigint*config.audio_micros;
 IF (NEW.status='succeeded' AND (NEW.reason_code<>'' OR NEW.cost_micros<>amount
  OR NOT EXISTS (SELECT 1 FROM clinic_app.ai_aiartifact a
   WHERE a.invocation_id=NEW.id AND a.kind='output')))
 OR (NEW.status='failed' AND (
  NEW.reason_code<>ALL(ARRAY['disabled','budget_exhausted',
  'configuration_unavailable','circuit_open','provider_timeout',
  'provider_unavailable','invalid_output','authority_revoked'])
  OR NEW.cost_micros<>CASE WHEN NEW.reason_code=ANY(ARRAY[
   'provider_timeout','provider_unavailable','invalid_output'])
   THEN OLD.reserved_micros ELSE 0 END))
 OR NEW.status NOT IN ('succeeded','failed')
 OR NEW.cost_minor<>(NEW.cost_micros+9999)/10000 THEN
  RAISE EXCEPTION 'AI terminal receipt denied' USING ERRCODE='23514';
 END IF;
 NEW.settled_at:=statement_timestamp();
 RETURN NEW;
END $function$
"

