function agent_action_payload(uuid, text.definition:
"CREATE OR REPLACE FUNCTION clinic_app.agent_action_payload(requested uuid, kek text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'clinic_app', 'pg_temp'
AS $function$
DECLARE value bytea;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM clinic_app.agent_proposal_scope(requested)) THEN
  RETURN NULL;
 END IF;
 SELECT payload INTO value FROM clinic_app.ai_actionproposal WHERE id=requested;
 RETURN convert_from(clinic_app.tenant_decrypt(
  kek,'ai.action_proposal.payload.v1',value),'UTF8');
END $function$
"

