function ai_review_extraction(uuid, uuid.definition:
"CREATE OR REPLACE FUNCTION clinic_app.ai_review_extraction(requested uuid, target uuid, decision text, source bytea, kek text)
 RETURNS TABLE(observation_id uuid, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'clinic_app', 'pg_temp'
AS $function$
DECLARE c clinic_app.ai_extractioncandidate; j clinic_app.ai_extractionjob;
 v clinic_app.orders_resultversion; p jsonb; expected jsonb; supplied jsonb;
 parsed text; source_type text; filed_unit text;
 identifier uuid; actor uuid:=NULLIF(current_setting('app.current_user_id',true),'')::uuid;
BEGIN
 SELECT * INTO c FROM clinic_app.ai_extractioncandidate WHERE id=requested;
 SELECT * INTO j FROM clinic_app.ai_extractionjob WHERE id=c.job_id;
 IF c.id IS NULL OR c.organization_id IS DISTINCT FROM NULLIF(current_setting('app.current_tenant',true),'')::uuid
 OR NOT clinic_app.ai_extraction_job_allowed(j.id)
 OR NOT clinic_app.has_permission('clinical.write',j.clinic_id,j.patient_enrollment_id)
 OR decision IS NULL OR decision NOT IN ('confirmed','rejected') THEN
  RAISE EXCEPTION 'extraction denied' USING ERRCODE='42501'; END IF;
 IF decision='confirmed' THEN
  IF NOT clinic_app.ai_effect_current(j.invocation_id,j.clinic_id) THEN
   RAISE EXCEPTION 'extraction invocation permission required' USING ERRCODE='42501';
  END IF;
  SELECT * INTO v FROM clinic_app.orders_resultversion WHERE id=target;
  IF v.id IS NULL OR (v.organization_id,v.clinic_id,v.sha256) IS DISTINCT FROM
    (j.organization_id,j.clinic_id,j.sha256)
  OR (j.result_version_id IS NOT NULL AND j.result_version_id<>v.id) THEN
   RAISE EXCEPTION 'extraction denied' USING ERRCODE='42501'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('orders-series:'||v.result_id,0));
 END IF;
 SELECT * INTO c FROM clinic_app.ai_extractioncandidate WHERE id=requested FOR UPDATE;
 IF c.status=decision AND c.reviewed_by_id=actor AND
   (decision='rejected' OR EXISTS(SELECT 1 FROM clinic_app.orders_resultobservation o
     WHERE o.id=c.observation_id AND o.version_id=target))
 THEN RETURN QUERY SELECT c.observation_id,false; RETURN; END IF;
 IF c.status NOT IN ('candidate','ambiguous') OR c.expires_at<=statement_timestamp()
 THEN RAISE EXCEPTION 'extraction decision stale' USING ERRCODE='40001'; END IF;
 IF decision='rejected' THEN
  UPDATE clinic_app.ai_extractioncandidate SET status='rejected',
   reviewed_by_id=actor,reviewed_at=statement_timestamp() WHERE id=c.id;
  RETURN QUERY SELECT NULL::uuid,true; RETURN;
 END IF;
 IF c.status<>'candidate' OR NOT clinic_app.orders_is_current(v.id)
 OR NOT EXISTS(SELECT 1 FROM clinic_app.orders_resultmatch m
  JOIN clinic_app.orders_order o ON o.id=m.order_id
   AND o.organization_id=j.organization_id AND o.clinic_id=j.clinic_id
  WHERE m.version_id=v.id AND m.organization_id=j.organization_id
  AND m.clinic_id=j.clinic_id AND o.enrollment_id=j.patient_enrollment_id)
 OR EXISTS(SELECT 1 FROM clinic_app.orders_resultacknowledgment a
  WHERE a.version_id=v.id)
 THEN RAISE EXCEPTION 'extraction filing denied' USING ERRCODE='23514'; END IF;
 IF j.attachment_id IS NULL THEN
  source_type:=v.content_type;
 ELSE
  SELECT a.detected_type INTO source_type
   FROM clinic_app.ehr_clinicalattachment a WHERE a.id=j.attachment_id;
 END IF;
 IF source_type IS NULL THEN
  RAISE EXCEPTION 'extraction filing denied' USING ERRCODE='23514'; END IF;
 p:=convert_from(clinic_app.tenant_decrypt(
  kek,'ai.extraction.candidate.v1',c.payload),'UTF8')::jsonb;
 IF jsonb_typeof(p) IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'extraction value unresolved' USING ERRCODE='23514'; END IF;
 IF NOT p ?& ARRAY['field','kind','raw_text','value','parsed_value','unit',
  'reference_interval','region','status','reason']
 OR p-ARRAY['field','kind','raw_text','value','parsed_value','unit',
  'reference_interval','region','status','reason']<>'{}'::jsonb
 OR EXISTS(SELECT 1 FROM jsonb_each(p) x WHERE x.key<>'region'
  AND jsonb_typeof(x.value)<>'string')
 OR jsonb_typeof(p->'region') IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'extraction value unresolved' USING ERRCODE='23514'; END IF;
 IF NOT (p->'region') ?& ARRAY['page','bbox']
 OR (p->'region')-ARRAY['page','bbox']<>'{}'::jsonb
 OR jsonb_typeof(p->'region'->'page') IS DISTINCT FROM 'number'
 OR p->'region'->>'page'!~'^[1-9][0-9]?$'
 OR (p->'region'->>'page')::int>jsonb_array_length(j.rotations)
 OR jsonb_typeof(p->'region'->'bbox') IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'extraction region unresolved' USING ERRCODE='23514'; END IF;
 IF jsonb_array_length(p->'region'->'bbox')<>4
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p->'region'->'bbox') x
  WHERE jsonb_typeof(x)<>'number' OR x::text!~'^[0-9]{1,5}$'
  OR x::text::int>10000)
 OR (p->'region'->'bbox'->>0)::int>=(p->'region'->'bbox'->>2)::int
 OR (p->'region'->'bbox'->>1)::int>=(p->'region'->'bbox'->>3)::int THEN
  RAISE EXCEPTION 'extraction region unresolved' USING ERRCODE='23514'; END IF;
 IF p->>'status'<>'candidate' OR p->>'reason'<>''
 OR p->>'field'!~'^[a-z][a-z0-9_]{0,31}$'
 OR length(p->>'raw_text')>1024 OR length(p->>'value') NOT BETWEEN 1 AND 128
 OR length(p->>'reference_interval')>256
 OR position(p->>'value' IN p->>'raw_text')=0
 OR (p->>'reference_interval'<>'' AND
  position(p->>'reference_interval' IN p->>'raw_text')=0)
 THEN RAISE EXCEPTION 'extraction value unresolved' USING ERRCODE='23514'; END IF;
 filed_unit:=p->>'unit';
 IF p->>'kind'='decimal' THEN
  IF p->>'value'!~('^[+-]?((0|[1-9][0-9]*)(,[0-9]+)?|'
   '[1-9][0-9]{0,2}(\.[0-9]{3})+,[0-9]+)$')
  THEN
   RAISE EXCEPTION 'extraction value unresolved' USING ERRCODE='23514'; END IF;
   IF source_type='application/pdf' THEN
    supplied:=convert_from(clinic_app.tenant_decrypt(
     kek,'orders.observation.source',source),'UTF8')::jsonb;
    filed_unit:=supplied->>'unit';
    IF p->>'unit'<>''
    OR p->>'raw_text' IS DISTINCT FROM (
       (p->>'field')||': '||(p->>'value')||CASE
        WHEN p->>'reference_interval'='' THEN ''
        ELSE ' ['||(p->>'reference_interval')||']' END)
    OR supplied->>'unit_entry' IS DISTINCT FROM 'clinician'
    OR jsonb_typeof(supplied->'unit') IS DISTINCT FROM 'string'
    OR length(filed_unit) NOT BETWEEN 1 AND 64
    OR filed_unit!~'^[[:print:]]+$'
    OR filed_unit~'^[[:space:]]|[[:space:]]$' THEN
     RAISE EXCEPTION 'extraction manual unit required' USING ERRCODE='23514'; END IF;
   ELSIF p->>'unit'<>ALL(ARRAY['mg/dL','g/dL','mmol/L','mEq/L','U/L','ng/mL','pg/mL',
   'mcg/L',U&'\00B5g/L',U&'10^3/\00B5L',U&'10^6/\00B5L',
   '%','mL','L','kg','g','cm','m',
   'mmHg','bpm','kg/m2','1'])
  OR position(p->>'unit' IN p->>'raw_text')=0 THEN
   RAISE EXCEPTION 'extraction value unresolved' USING ERRCODE='23514'; END IF;
  parsed:=replace(replace(p->>'value','.',''),',','.');
 ELSIF p->>'kind'='date' AND p->>'unit'='' AND
  p->>'value'~'^[0-9]{2}/[0-9]{2}/[0-9]{4}$' THEN
  BEGIN
   parsed:=to_char(make_date(substring(p->>'value',7,4)::int,
    substring(p->>'value',4,2)::int,substring(p->>'value',1,2)::int),'YYYY-MM-DD');
  EXCEPTION WHEN datetime_field_overflow THEN
   RAISE EXCEPTION 'extraction value unresolved' USING ERRCODE='23514';
  END;
 ELSE RAISE EXCEPTION 'extraction value unresolved' USING ERRCODE='23514'; END IF;
 IF parsed IS DISTINCT FROM p->>'parsed_value' THEN
  RAISE EXCEPTION 'extraction value unresolved' USING ERRCODE='23514'; END IF;
 expected:=jsonb_build_object('code',p->>'field','value',p->>'value',
  'parsed_value',parsed,'unit',filed_unit,'reference_interval',p->>'reference_interval',
  'abnormal_flag','','provenance','imported','confirmer',actor::text,
  'page',p->'region'->'page','bbox',p->'region'->'bbox','raw_text',p->>'raw_text',
  'extraction_candidate',c.id::text);
 IF source_type='application/pdf' AND p->>'kind'='decimal' THEN
  expected:=expected||'{"unit_entry":"clinician"}'::jsonb;
 ELSE
  supplied:=convert_from(clinic_app.tenant_decrypt(
   kek,'orders.observation.source',source),'UTF8')::jsonb;
 END IF;
 IF supplied IS DISTINCT FROM expected THEN
  RAISE EXCEPTION 'extraction payload mismatch' USING ERRCODE='23514'; END IF;
 identifier:=gen_random_uuid();
 -- The FK is deferred. The uncommitted marker admits only this exact row,
 -- created in this function, and cannot be forged through runtime table ACLs.
 UPDATE clinic_app.ai_extractioncandidate SET status='confirmed',
  reviewed_by_id=actor,reviewed_at=statement_timestamp(),observation_id=identifier
  WHERE id=c.id;
 INSERT INTO clinic_app.orders_resultobservation
 (id,organization_id,clinic_id,created_at,version_id,position,source)
 VALUES(identifier,j.organization_id,j.clinic_id,statement_timestamp(),v.id,
  (SELECT count(*) FROM clinic_app.orders_resultobservation o
   WHERE o.version_id=v.id),source);
 RETURN QUERY SELECT identifier,true;
EXCEPTION WHEN data_exception THEN
 RAISE EXCEPTION 'extraction data invalid' USING ERRCODE='23514';
END $function$
"

function ai_review_extraction(uuid, uuid.prosrc:
"
DECLARE c clinic_app.ai_extractioncandidate; j clinic_app.ai_extractionjob;
 v clinic_app.orders_resultversion; p jsonb; expected jsonb; supplied jsonb;
 parsed text; source_type text; filed_unit text;
 identifier uuid; actor uuid:=NULLIF(current_setting('app.current_user_id',true),'')::uuid;
BEGIN
 SELECT * INTO c FROM clinic_app.ai_extractioncandidate WHERE id=requested;
 SELECT * INTO j FROM clinic_app.ai_extractionjob WHERE id=c.job_id;
 IF c.id IS NULL OR c.organization_id IS DISTINCT FROM NULLIF(current_setting('app.current_tenant',true),'')::uuid
 OR NOT clinic_app.ai_extraction_job_allowed(j.id)
 OR NOT clinic_app.has_permission('clinical.write',j.clinic_id,j.patient_enrollment_id)
 OR decision IS NULL OR decision NOT IN ('confirmed','rejected') THEN
  RAISE EXCEPTION 'extraction denied' USING ERRCODE='42501'; END IF;
 IF decision='confirmed' THEN
  IF NOT clinic_app.ai_effect_current(j.invocation_id,j.clinic_id) THEN
   RAISE EXCEPTION 'extraction invocation permission required' USING ERRCODE='42501';
  END IF;
  SELECT * INTO v FROM clinic_app.orders_resultversion WHERE id=target;
  IF v.id IS NULL OR (v.organization_id,v.clinic_id,v.sha256) IS DISTINCT FROM
    (j.organization_id,j.clinic_id,j.sha256)
  OR (j.result_version_id IS NOT NULL AND j.result_version_id<>v.id) THEN
   RAISE EXCEPTION 'extraction denied' USING ERRCODE='42501'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('orders-series:'||v.result_id,0));
 END IF;
 SELECT * INTO c FROM clinic_app.ai_extractioncandidate WHERE id=requested FOR UPDATE;
 IF c.status=decision AND c.reviewed_by_id=actor AND
   (decision='rejected' OR EXISTS(SELECT 1 FROM clinic_app.orders_resultobservation o
     WHERE o.id=c.observation_id AND o.version_id=target))
 THEN RETURN QUERY SELECT c.observation_id,false; RETURN; END IF;
 IF c.status NOT IN ('candidate','ambiguous') OR c.expires_at<=statement_timestamp()
 THEN RAISE EXCEPTION 'extraction decision stale' USING ERRCODE='40001'; END IF;
 IF decision='rejected' THEN
  UPDATE clinic_app.ai_extractioncandidate SET status='rejected',
   reviewed_by_id=actor,reviewed_at=statement_timestamp() WHERE id=c.id;
  RETURN QUERY SELECT NULL::uuid,true; RETURN;
 END IF;
 IF c.status<>'candidate' OR NOT clinic_app.orders_is_current(v.id)
 OR NOT EXISTS(SELECT 1 FROM clinic_app.orders_resultmatch m
  JOIN clinic_app.orders_order o ON o.id=m.order_id
   AND o.organization_id=j.organization_id AND o.clinic_id=j.clinic_id
  WHERE m.version_id=v.id AND m.organization_id=j.organization_id
  AND m.clinic_id=j.clinic_id AND o.enrollment_id=j.patient_enrollment_id)
 OR EXISTS(SELECT 1 FROM clinic_app.orders_resultacknowledgment a
  WHERE a.version_id=v.id)
 THEN RAISE EXCEPTION 'extraction filing denied' USING ERRCODE='23514'; END IF;
 IF j.attachment_id IS NULL THEN
  source_type:=v.content_type;
 ELSE
  SELECT a.detected_type INTO source_type
   FROM clinic_app.ehr_clinicalattachment a WHERE a.id=j.attachment_id;
 END IF;
 IF source_type IS NULL THEN
  RAISE EXCEPTION 'extraction filing denied' USING ERRCODE='23514'; END IF;
 p:=convert_from(clinic_app.tenant_decrypt(
  kek,'ai.extraction.candidate.v1',c.payload),'UTF8')::jsonb;
 IF jsonb_typeof(p) IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'extraction value unresolved' USING ERRCODE='23514'; END IF;
 IF NOT p ?& ARRAY['field','kind','raw_text','value','parsed_value','unit',
  'reference_interval','region','status','reason']
 OR p-ARRAY['field','kind','raw_text','value','parsed_value','unit',
  'reference_interval','region','status','reason']<>'{}'::jsonb
 OR EXISTS(SELECT 1 FROM jsonb_each(p) x WHERE x.key<>'region'
  AND jsonb_typeof(x.value)<>'string')
 OR jsonb_typeof(p->'region') IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'extraction value unresolved' USING ERRCODE='23514'; END IF;
 IF NOT (p->'region') ?& ARRAY['page','bbox']
 OR (p->'region')-ARRAY['page','bbox']<>'{}'::jsonb
 OR jsonb_typeof(p->'region'->'page') IS DISTINCT FROM 'number'
 OR p->'region'->>'page'!~'^[1-9][0-9]?$'
 OR (p->'region'->>'page')::int>jsonb_array_length(j.rotations)
 OR jsonb_typeof(p->'region'->'bbox') IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'extraction region unresolved' USING ERRCODE='23514'; END IF;
 IF jsonb_array_length(p->'region'->'bbox')<>4
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p->'region'->'bbox') x
  WHERE jsonb_typeof(x)<>'number' OR x::text!~'^[0-9]{1,5}$'
  OR x::text::int>10000)
 OR (p->'region'->'bbox'->>0)::int>=(p->'region'->'bbox'->>2)::int
 OR (p->'region'->'bbox'->>1)::int>=(p->'region'->'bbox'->>3)::int THEN
  RAISE EXCEPTION 'extraction region unresolved' USING ERRCODE='23514'; END IF;
 IF p->>'status'<>'candidate' OR p->>'reason'<>''
 OR p->>'field'!~'^[a-z][a-z0-9_]{0,31}$'
 OR length(p->>'raw_text')>1024 OR length(p->>'value') NOT BETWEEN 1 AND 128
 OR length(p->>'reference_interval')>256
 OR position(p->>'value' IN p->>'raw_text')=0
 OR (p->>'reference_interval'<>'' AND
  position(p->>'reference_interval' IN p->>'raw_text')=0)
 THEN RAISE EXCEPTION 'extraction value unresolved' USING ERRCODE='23514'; END IF;
 filed_unit:=p->>'unit';
 IF p->>'kind'='decimal' THEN
  IF p->>'value'!~('^[+-]?((0|[1-9][0-9]*)(,[0-9]+)?|'
   '[1-9][0-9]{0,2}(\.[0-9]{3})+,[0-9]+)$')
  THEN
   RAISE EXCEPTION 'extraction value unresolved' USING ERRCODE='23514'; END IF;
   IF source_type='application/pdf' THEN
    supplied:=convert_from(clinic_app.tenant_decrypt(
     kek,'orders.observation.source',source),'UTF8')::jsonb;
    filed_unit:=supplied->>'unit';
    IF p->>'unit'<>''
    OR p->>'raw_text' IS DISTINCT FROM (
       (p->>'field')||': '||(p->>'value')||CASE
        WHEN p->>'reference_interval'='' THEN ''
        ELSE ' ['||(p->>'reference_interval')||']' END)
    OR supplied->>'unit_entry' IS DISTINCT FROM 'clinician'
    OR jsonb_typeof(supplied->'unit') IS DISTINCT FROM 'string'
    OR length(filed_unit) NOT BETWEEN 1 AND 64
    OR filed_unit!~'^[[:print:]]+$'
    OR filed_unit~'^[[:space:]]|[[:space:]]$' THEN
     RAISE EXCEPTION 'extraction manual unit required' USING ERRCODE='23514'; END IF;
   ELSIF p->>'unit'<>ALL(ARRAY['mg/dL','g/dL','mmol/L','mEq/L','U/L','ng/mL','pg/mL',
   'mcg/L',U&'\00B5g/L',U&'10^3/\00B5L',U&'10^6/\00B5L',
   '%','mL','L','kg','g','cm','m',
   'mmHg','bpm','kg/m2','1'])
  OR position(p->>'unit' IN p->>'raw_text')=0 THEN
   RAISE EXCEPTION 'extraction value unresolved' USING ERRCODE='23514'; END IF;
  parsed:=replace(replace(p->>'value','.',''),',','.');
 ELSIF p->>'kind'='date' AND p->>'unit'='' AND
  p->>'value'~'^[0-9]{2}/[0-9]{2}/[0-9]{4}$' THEN
  BEGIN
   parsed:=to_char(make_date(substring(p->>'value',7,4)::int,
    substring(p->>'value',4,2)::int,substring(p->>'value',1,2)::int),'YYYY-MM-DD');
  EXCEPTION WHEN datetime_field_overflow THEN
   RAISE EXCEPTION 'extraction value unresolved' USING ERRCODE='23514';
  END;
 ELSE RAISE EXCEPTION 'extraction value unresolved' USING ERRCODE='23514'; END IF;
 IF parsed IS DISTINCT FROM p->>'parsed_value' THEN
  RAISE EXCEPTION 'extraction value unresolved' USING ERRCODE='23514'; END IF;
 expected:=jsonb_build_object('code',p->>'field','value',p->>'value',
  'parsed_value',parsed,'unit',filed_unit,'reference_interval',p->>'reference_interval',
  'abnormal_flag','','provenance','imported','confirmer',actor::text,
  'page',p->'region'->'page','bbox',p->'region'->'bbox','raw_text',p->>'raw_text',
  'extraction_candidate',c.id::text);
 IF source_type='application/pdf' AND p->>'kind'='decimal' THEN
  expected:=expected||'{"unit_entry":"clinician"}'::jsonb;
 ELSE
  supplied:=convert_from(clinic_app.tenant_decrypt(
   kek,'orders.observation.source',source),'UTF8')::jsonb;
 END IF;
 IF supplied IS DISTINCT FROM expected THEN
  RAISE EXCEPTION 'extraction payload mismatch' USING ERRCODE='23514'; END IF;
 identifier:=gen_random_uuid();
 -- The FK is deferred. The uncommitted marker admits only this exact row,
 -- created in this function, and cannot be forged through runtime table ACLs.
 UPDATE clinic_app.ai_extractioncandidate SET status='confirmed',
  reviewed_by_id=actor,reviewed_at=statement_timestamp(),observation_id=identifier
  WHERE id=c.id;
 INSERT INTO clinic_app.orders_resultobservation
 (id,organization_id,clinic_id,created_at,version_id,position,source)
 VALUES(identifier,j.organization_id,j.clinic_id,statement_timestamp(),v.id,
  (SELECT count(*) FROM clinic_app.orders_resultobservation o
   WHERE o.version_id=v.id),source);
 RETURN QUERY SELECT identifier,true;
EXCEPTION WHEN data_exception THEN
 RAISE EXCEPTION 'extraction data invalid' USING ERRCODE='23514';
END "

function billing_fiscal_guard().definition:
"CREATE OR REPLACE FUNCTION clinic_app.billing_fiscal_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'clinic_app', 'pg_temp'
AS $function$
DECLARE cfg clinic_app.billing_fiscalconfiguration;
 charge clinic_app.billing_invoice;
BEGIN
 IF TG_OP IN ('DELETE','TRUNCATE')
 OR TG_TABLE_NAME='billing_fiscaltransition' THEN
  RAISE EXCEPTION 'fiscal history is immutable' USING ERRCODE='23514';
 END IF;
 IF TG_TABLE_NAME='billing_fiscalconfiguration' THEN
  IF TG_OP<>'INSERT' THEN
   RAISE EXCEPTION 'fiscal review is immutable' USING ERRCODE='23514';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM clinic_app.billing_journalbook b
  WHERE b.id=NEW.book_id AND b.clinic_id=NEW.clinic_id
  AND b.organization_id=NEW.organization_id)
  OR NEW.provider NOT IN ('national','aggregator')
  OR NEW.review_kind NOT IN ('unreviewed','synthetic_fixture','eg9')
  OR NEW.ibs_cbs_applicability NOT IN ('undecided','applicable','not_applicable')
  OR NEW.cancellation_window_seconds<1 THEN
   RAISE EXCEPTION 'invalid fiscal configuration' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
 END IF;
 IF NOT clinic_app.billing_fiscal_access(NEW.clinic_id) THEN
  RAISE EXCEPTION 'billing access denied' USING ERRCODE='42501';
 END IF;
 SELECT * INTO cfg FROM clinic_app.billing_fiscalconfiguration
 WHERE id=NEW.configuration_id;
 IF cfg.id IS NULL OR cfg.organization_id IS DISTINCT FROM NEW.organization_id
 OR cfg.clinic_id IS DISTINCT FROM NEW.clinic_id
 OR cfg.book_id IS DISTINCT FROM NEW.book_id
 OR cfg.legal_entity_reference IS DISTINCT FROM NEW.legal_entity_reference
 OR cfg.provider IS DISTINCT FROM NEW.provider
 OR cfg.municipality_code IS DISTINCT FROM NEW.municipality_code
 OR cfg.service_code IS DISTINCT FROM NEW.service_code
 OR cfg.review_reference IS NULL OR cfg.reviewed_at IS NULL
 OR cfg.reviewed_at>statement_timestamp() OR cfg.expires_at IS NULL
 OR cfg.ibs_cbs_applicability NOT IN ('applicable','not_applicable')
 OR (NEW.rehearsal AND cfg.review_kind<>'synthetic_fixture')
 OR (NOT NEW.rehearsal AND cfg.review_kind<>'eg9') THEN
  RAISE EXCEPTION 'fiscal configuration unreviewed' USING ERRCODE='23514';
 END IF;
 IF NOT NEW.rehearsal AND NEW.status<>'draft' THEN
  RAISE EXCEPTION 'BLOCKED-ON-EG' USING ERRCODE='23514';
 END IF;
 IF TG_OP='INSERT' THEN
  SELECT * INTO charge FROM clinic_app.billing_invoice WHERE id=NEW.invoice_id;
  IF charge.id IS NULL OR charge.organization_id IS DISTINCT FROM NEW.organization_id
  OR charge.clinic_id IS DISTINCT FROM NEW.clinic_id
  OR charge.state NOT IN ('open','paid') OR charge.currency<>'BRL'
  OR NEW.amount_minor IS DISTINCT FROM charge.amount_minor
  OR cfg.expires_at<=statement_timestamp()
  OR NEW.status<>'draft' OR NEW.create_command_id<>NEW.last_command_id
  OR octet_length(NEW.create_fingerprint)<>32
  OR NEW.submitted_at IS NOT NULL OR NEW.authorized_at IS NOT NULL
  OR NEW.cancel_until IS NOT NULL OR NEW.cancelled_at IS NOT NULL
  OR NEW.xml_reference IS NOT NULL OR NEW.pdf_reference IS NOT NULL
  OR NEW.xml_payload IS NOT NULL OR NEW.pdf_payload IS NOT NULL
  OR NEW.cancellation_payload IS NOT NULL OR NEW.provider_reference IS NOT NULL
  OR NEW.rejection_code<>'' THEN
   RAISE EXCEPTION 'invalid fiscal document binding' USING ERRCODE='23514';
  END IF;
  -- The same purpose protects the reviewed terms and their immutable snapshot.
  -- A direct runtime INSERT cannot substitute unreviewed tax fields.
  NEW.tax_fields := cfg.tax_fields;
  RETURN NEW;
 END IF;
 IF to_jsonb(NEW)-ARRAY['status','last_command_id','xml_payload','pdf_payload',
 'cancellation_payload','xml_reference','pdf_reference','provider_reference',
 'rejection_code'] IS DISTINCT FROM
 to_jsonb(OLD)-ARRAY['status','last_command_id','xml_payload','pdf_payload',
 'cancellation_payload','xml_reference','pdf_reference','provider_reference',
 'rejection_code'] OR NEW.last_command_id=OLD.last_command_id THEN
  RAISE EXCEPTION 'immutable fiscal terms' USING ERRCODE='23514';
 END IF;
 IF OLD.status='draft' AND NEW.status='submitted' THEN
  IF cfg.expires_at<=statement_timestamp()
  OR ROW(NEW.xml_payload,NEW.pdf_payload,NEW.cancellation_payload,
   NEW.xml_reference,NEW.pdf_reference,NEW.provider_reference,NEW.rejection_code)
  IS DISTINCT FROM ROW(OLD.xml_payload,OLD.pdf_payload,OLD.cancellation_payload,
   OLD.xml_reference,OLD.pdf_reference,OLD.provider_reference,OLD.rejection_code) THEN
   RAISE EXCEPTION 'invalid fiscal submission' USING ERRCODE='23514';
  END IF;
  NEW.submitted_at := statement_timestamp();
 ELSIF OLD.status='submitted' AND NEW.status='authorized' THEN
  IF NEW.xml_payload IS NULL OR NEW.xml_reference IS DISTINCT FROM NEW.id
  OR NEW.provider_reference IS NULL OR NEW.rejection_code<>''
  OR NEW.cancellation_payload IS NOT NULL
  OR (NEW.pdf_payload IS NULL AND NEW.pdf_reference IS NOT NULL)
  OR (NEW.pdf_payload IS NOT NULL AND NEW.pdf_reference IS DISTINCT FROM NEW.id) THEN
   RAISE EXCEPTION 'invalid fiscal authorization' USING ERRCODE='23514';
  END IF;
  NEW.authorized_at := statement_timestamp();
  NEW.cancel_until := NEW.authorized_at
   +make_interval(secs=>cfg.cancellation_window_seconds);
 ELSIF OLD.status='submitted' AND NEW.status='rejected' THEN
  IF NEW.rejection_code !~ '^[A-Z][A-Z0-9_]{0,15}$'
  OR NEW.xml_payload IS NOT NULL OR NEW.pdf_payload IS NOT NULL
  OR NEW.cancellation_payload IS NOT NULL OR NEW.xml_reference IS NOT NULL
  OR NEW.pdf_reference IS NOT NULL OR NEW.provider_reference IS NOT NULL THEN
   RAISE EXCEPTION 'invalid fiscal rejection' USING ERRCODE='23514';
  END IF;
 ELSIF OLD.status IN ('draft','authorized') AND NEW.status='cancelled' THEN
  IF ROW(NEW.xml_payload,NEW.pdf_payload,NEW.xml_reference,NEW.pdf_reference,
   NEW.provider_reference,NEW.rejection_code)
  IS DISTINCT FROM ROW(OLD.xml_payload,OLD.pdf_payload,OLD.xml_reference,
   OLD.pdf_reference,OLD.provider_reference,OLD.rejection_code)
  OR (OLD.status='authorized' AND (OLD.cancel_until IS NULL
   OR statement_timestamp()>=OLD.cancel_until
   OR NEW.cancellation_payload IS NULL))
  OR (OLD.status='draft' AND NEW.cancellation_payload IS NOT NULL) THEN
   RAISE EXCEPTION 'fiscal cancellation refused' USING ERRCODE='23514';
  END IF;
  NEW.cancelled_at := statement_timestamp();
 ELSE
  RAISE EXCEPTION 'fiscal transition denied' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $function$
"

