function identity_session_register(uuid,.prosrc:
"
DECLARE
    result uuid;
BEGIN
    IF requested_hash IS NULL OR octet_length(requested_hash) <> 32
       OR requested_user IS DISTINCT FROM NULLIF(
           current_setting('app.current_user_id', true), ''
       )::uuid
       OR requested_expiry IS NULL OR requested_expiry <= statement_timestamp()
       OR requested_network IS NULL OR requested_family IS NULL
       OR requested_family NOT IN ('chromium', 'firefox', 'safari', 'other')
       OR NULLIF(current_setting('app.current_principal', true), '') IS NOT NULL
       OR NULLIF(current_setting('app.current_patient_session', true), '') IS NOT NULL
       OR NOT EXISTS (
           SELECT 1 FROM clinic_app.identity_user
           WHERE id = requested_user AND is_active
       )
    THEN
        RETURN NULL;
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended(
        'clinic-lock-v1:user:' || requested_user::text, 0
    ));
    INSERT INTO clinic_app.identity_sessionrecord (
        id, user_id, session_key_hash, created_at, last_seen, ip_network,
        user_agent_family, expires_at, revoked_at, verification_device_id, verified_at
    ) VALUES (
        gen_random_uuid(), requested_user, requested_hash, statement_timestamp(),
        statement_timestamp(), requested_network, requested_family, requested_expiry,
        NULL, NULL, NULL
    )
    ON CONFLICT (session_key_hash) DO NOTHING
    RETURNING id INTO result;
    IF result IS NULL THEN
        SELECT id INTO result FROM clinic_app.identity_sessionrecord
        WHERE session_key_hash = requested_hash AND user_id = requested_user
          AND revoked_at IS NULL AND expires_at > statement_timestamp();
    END IF;
    RETURN result;
END
"

function identity_offboarding_execute(uu.definition:
"CREATE OR REPLACE FUNCTION clinic_app.identity_offboarding_execute(requested_user uuid, requested_clinic uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    current_organization uuid;
    account_active boolean;
BEGIN
    IF clinic_app.identity_offboarding_clinics(
        requested_user, requested_clinic
    ) IS NULL THEN
        RETURN false;
    END IF;
    current_organization := NULLIF(
        current_setting('app.current_tenant', true), ''
    )::uuid;
    PERFORM pg_advisory_xact_lock(hashtextextended(
        'clinic-lock-v1:identity-owner:' || current_organization::text, 0
    ));
    PERFORM pg_advisory_xact_lock(hashtextextended(
        'clinic-lock-v1:user:' || requested_user::text, 0
    ));
    SELECT is_active INTO account_active FROM clinic_app.identity_user
    WHERE id = requested_user FOR UPDATE;
    IF NOT FOUND THEN
        RETURN false;
    END IF;
    IF NOT account_active THEN
        RETURN true;
    END IF;
    -- Authenticator rows before the memberships whose trigger takes the
    -- session key (one order: user row, authenticators, key, sessions).
    PERFORM clinic_app.identity_lock_authenticators(requested_user);
    IF EXISTS (
        SELECT 1 FROM clinic_app.identity_userclinicrole AS membership
        WHERE membership.user_id = requested_user AND membership.role = 'owner'
          AND membership.revoked_at IS NULL
          AND NOT EXISTS (
              SELECT 1 FROM clinic_app.identity_userclinicrole AS other
              JOIN clinic_app.identity_user AS account ON account.id = other.user_id
              WHERE other.organization_id = membership.organization_id
                AND other.role = 'owner' AND other.revoked_at IS NULL
                AND other.user_id <> requested_user AND account.is_active
          )
    ) OR EXISTS (
        SELECT 1 FROM clinic_app.scheduling_appointment
        WHERE practitioner_id = requested_user AND status = 'scheduled'
          AND end_at > statement_timestamp()
    ) OR EXISTS (
        SELECT 1 FROM clinic_app.scheduling_availabilityblock
        WHERE practitioner_id = requested_user AND retired_at IS NULL
          AND end_at > statement_timestamp()
    ) THEN
        RETURN false;
    END IF;
    UPDATE clinic_app.identity_userclinicrole
    SET revoked_at = statement_timestamp()
    WHERE user_id = requested_user AND revoked_at IS NULL;
    PERFORM clinic_app.identity_retire_authenticators(requested_user);
    UPDATE clinic_app.identity_user SET is_active = false WHERE id = requested_user;
    RETURN true;
END
$function$
"

